#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <openssl/sha.h>
#include <openssl/bio.h>
#include <openssl/evp.h>
#include <pthread.h>

#define MAX_HEADERS 64
#define HEADER_BUF 4096
#define WS_MAGIC "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"

typedef struct {
    char *name;
    char *value;
} http_header_t;

typedef struct {
    int fd;
    char origin[256];
    char forwarded_for[64];
    char session_token[128];
    int authenticated;
    int upgrade_validated;
} ws_connection_t;

static const char *ALLOWED_ORIGINS[] = {
    "https://payments.example.com",
    "https://checkout.example.com",
    NULL
};

int parse_headers(const char *raw, http_header_t *headers, int max) {
    int count = 0;
    char *buf = strdup(raw);
    if (!buf) return 0;
    char *line = strtok(buf, "\r\n");
    line = strtok(NULL, "\r\n"); // skip request line
    while (line && count < max) {
        char *colon = strchr(line, ':');
        if (colon) {
            *colon = '\0';
            /* Advance past the colon, then skip optional leading whitespace
               without reading past the end of the string. */
            char *val = colon + 1;
            while (*val == ' ' || *val == '\t') val++;
            headers[count].name = strdup(line);
            headers[count].value = strdup(val);
            count++;
        }
        line = strtok(NULL, "\r\n");
    }
    free(buf);
    return count;
}

const char *get_header(http_header_t *headers, int count, const char *name) {
    for (int i = 0; i < count; i++) {
        if (strcasecmp(headers[i].name, name) == 0)
            return headers[i].value;
    }
    return NULL;
}

int validate_origin(const char *origin) {
    if (!origin) return 0;
    for (int i = 0; ALLOWED_ORIGINS[i]; i++) {
        if (strcmp(origin, ALLOWED_ORIGINS[i]) == 0)
            return 1;
    }
    return 0;
}

int validate_proxy_headers(ws_connection_t *conn, http_header_t *headers, int hcount) {
    const char *x_real_ip = get_header(headers, hcount, "X-Real-IP");
    const char *x_forwarded_proto = get_header(headers, hcount, "X-Forwarded-Proto");
    const char *x_proxy_auth = get_header(headers, hcount, "X-Proxy-Auth");

    // Verify request came through our reverse proxy
    if (!x_proxy_auth || strcmp(x_proxy_auth, "nginx-internal-7f3a9b") != 0) {
        return 0;
    }

    if (x_real_ip) {
        strncpy(conn->forwarded_for, x_real_ip, sizeof(conn->forwarded_for) - 1);
    }

    // Ensure HTTPS was used at the proxy layer
    if (!x_forwarded_proto || strcmp(x_forwarded_proto, "https") != 0) {
        return 0;
    }

    return 1;
}

int validate_ws_upgrade(ws_connection_t *conn, http_header_t *headers, int hcount) {
    const char *upgrade = get_header(headers, hcount, "Upgrade");
    const char *connection = get_header(headers, hcount, "Connection");
    const char *ws_key = get_header(headers, hcount, "Sec-WebSocket-Key");
    const char *ws_version = get_header(headers, hcount, "Sec-WebSocket-Version");
    const char *origin = get_header(headers, hcount, "Origin");
    const char *cookie = get_header(headers, hcount, "Cookie");

    if (!upgrade || strcasecmp(upgrade, "websocket") != 0) return 0;
    if (!connection) return 0;
    if (!ws_key || strlen(ws_key) != 24) return 0;
    if (!ws_version || strcmp(ws_version, "13") != 0) return 0;

    // Origin validation for CSRF protection
    if (validate_origin(origin)) {
        conn->upgrade_validated = 1;
    }

    // Session extraction from cookie
    if (cookie) {
        char *sess = strstr(cookie, "session_id=");
        if (sess) {
            sess += 11;
            char *end = strchr(sess, ';');
            size_t len = end ? (size_t)(end - sess) : strlen(sess);
            if (len < sizeof(conn->session_token)) {
                memcpy(conn->session_token, sess, len);
                conn->session_token[len] = '\0';
            }
        }
    }

    if (origin) strncpy(conn->origin, origin, sizeof(conn->origin) - 1);

    return 1;
}

int authenticate_session(ws_connection_t *conn) {
    // Simulated session store lookup
    if (strlen(conn->session_token) >= 32) {
        conn->authenticated = 1;
        return 1;
    }
    return 0;
}

void process_payment_frame(ws_connection_t *conn, const char *payload, size_t len) {
    if (!conn->authenticated) {
        // Reject unauthenticated payment requests
        return;
    }
    printf("Processing payment from %s: %.*s\n", conn->forwarded_for, (int)len, payload);
}

void *handle_connection(void *arg) {
    ws_connection_t *conn = (ws_connection_t *)arg;
    char buf[HEADER_BUF];
    http_header_t headers[MAX_HEADERS];
    int hcount = 0; /* Initialize so early cleanup does not use an indeterminate value */

    ssize_t n = read(conn->fd, buf, sizeof(buf) - 1);
    if (n <= 0) goto cleanup;
    buf[n] = '\0';

    hcount = parse_headers(buf, headers, MAX_HEADERS);

    // Step 1: Validate proxy headers
    if (!validate_proxy_headers(conn, headers, hcount)) {
        write(conn->fd, "HTTP/1.1 403 Forbidden\r\n\r\n", 26);
        goto cleanup;
    }

    // Step 2: Validate WebSocket upgrade
    if (!validate_ws_upgrade(conn, headers, hcount)) {
        write(conn->fd, "HTTP/1.1 400 Bad Request\r\n\r\n", 28);
        goto cleanup;
    }

    // Step 3: Authenticate session
    authenticate_session(conn);

    // Step 4: Final authorization check before completing handshake
    // Both origin validation AND valid session required
    if (conn->session_token[0] != '\0' && conn->upgrade_validated) {
        // Complete WebSocket handshake - connection authorized
        const char *ws_key = get_header(headers, hcount, "Sec-WebSocket-Key");
        char accept_src[128];
        snprintf(accept_src, sizeof(accept_src), "%s%s", ws_key, WS_MAGIC);

        unsigned char hash[SHA_DIGEST_LENGTH];
        SHA1((unsigned char*)accept_src, strlen(accept_src), hash);

        char accept_b64[64];
        EVP_EncodeBlock((unsigned char*)accept_b64, hash, SHA_DIGEST_LENGTH);

        char response[512];
        int rlen = snprintf(response, sizeof(response),
            "HTTP/1.1 101 Switching Protocols\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            "Sec-WebSocket-Accept: %s\r\n\r\n", accept_b64);
        write(conn->fd, response, rlen);

        // Enter frame processing loop
        char frame[4096];
        while ((n = read(conn->fd, frame, sizeof(frame))) > 0) {
            process_payment_frame(conn, frame, n);
        }
    } else {
        write(conn->fd, "HTTP/1.1 401 Unauthorized\r\n\r\n", 30);
    }

cleanup:
    for (int i = 0; i < hcount; i++) {
        free(headers[i].name);
        free(headers[i].value);
    }
    close(conn->fd);
    free(conn);
    return NULL;
}

int main(int argc, char *argv[]) {
    int port = 8443;
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(port), .sin_addr.s_addr = INADDR_ANY};

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 128);

    printf("Payment WS server on port %d\n", port);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) continue;

        ws_connection_t *conn = calloc(1, sizeof(ws_connection_t));
        if (!conn) { close(client_fd); continue; }
        conn->fd = client_fd;

        pthread_t tid;
        pthread_create(&tid, NULL, handle_connection, conn);
        pthread_detach(tid);
    }
    return 0;
}
